// M5 Task 12: THIRD-PARTY.md and the list Settings → About → Licences shows
// (src/thirdParty.json) are one list, generated by lab/release/third-party.mjs
// from cargo metadata and the desktop package-lock, plus Mercury and Hamlib.
import { strict as assert } from "node:assert";
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const md = () => readFileSync(join(root, "THIRD-PARTY.md"), "utf8");
const json = () => JSON.parse(readFileSync(join(root, "apps", "desktop", "src", "thirdParty.json"), "utf8"));

/** The table rows of THIRD-PARTY.md: `| name | version | licence | ... |`. */
function mdRows() {
  return md()
    .split(/\r?\n/)
    .filter((l) => /^\| [^-|]/.test(l) && !l.startsWith("| Component "))
    .map((l) => l.split("|").slice(1, 4).map((c) => c.trim().replace(/^`|`$/g, "")))
    .map(([name, version, licence]) => `${name}@${version} ${licence}`);
}

test("THIRD-PARTY.md and About's licence list name the same components", () => {
  const fromJson = json().map((c) => `${c.name}@${c.version} ${c.licence}`);
  assert.ok(fromJson.length > 50, `only ${fromJson.length} components`);
  assert.deepEqual(mdRows(), fromJson);
});

test("every component has a licence, and the modem's parts are listed", () => {
  const list = json();
  for (const c of list) assert.ok(c.licence && c.licence.trim(), `${c.name} has no licence`);
  for (const name of ["Mercury", "Hamlib", "tauri", "vue"]) {
    assert.ok(list.some((c) => c.name === name), `${name} is missing`);
  }
});

test("the list is current: regenerating it changes nothing", () => {
  execFileSync(process.execPath, [join(root, "lab", "release", "third-party.mjs"), "--check"], { cwd: root, stdio: "pipe" });
});
